SET NOCOUNT ON; SELECT COUNT(*) AS 总, SUM(CASE WHEN [仓库] IS NOT NULL AND [仓库]<>'' THEN 1 ELSE 0 END) AS 头有仓库, SUM(CASE WHEN [仓库编码] IS NOT NULL AND [仓库编码]<>'' THEN 1 ELSE 0 END) AS 头有仓库编码 FROM bd_purchase_in; SELECT COUNT(*) AS 总, SUM(CASE WHEN [仓库] IS NOT NULL AND [仓库]<>'' THEN 1 ELSE 0 END) AS 销行有仓库, SUM(CASE WHEN [仓库名称] IS NOT NULL AND [仓库名称]<>'' THEN 1 ELSE 0 END) AS 销行有仓库名称 FROM bl_sale_out;